import { Suspense } from 'react'
import { getRelatedProducts } from '@/lib/data'

export default function ProductPage({
  searchParams,
}: {
  searchParams: Promise<Record<string, string | string[] | undefined>>
}) {
  return (
    <main>
      <h1>Premium Widget</h1>
      <p>A durable widget for everyday projects.</p>
      <section>
        <h2>Related products</h2>
        <Suspense fallback={<p>Loading related products...</p>}>
          <RelatedProducts searchParams={searchParams} />
        </Suspense>
      </section>
    </main>
  )
}

async function RelatedProducts({
  searchParams,
}: {
  searchParams: Promise<Record<string, string | string[] | undefined>>
}) {
  // Resolving searchParams makes this content depend on the destination URL,
  // so it is excluded from the shared App Shell (default prefetch) and only
  // resolved by a per-link prefetch with prefetch={true}.
  const params = await searchParams
  const urlKey = JSON.stringify(params)
  const relatedProducts = await getRelatedProducts(urlKey)

  return (
    <ul>
      {relatedProducts.map((product) => (
        <li key={product}>{product}</li>
      ))}
    </ul>
  )
}

